import numpy as np

def ichol(A):
    A = np.asarray(A)
    n = A.shape[0]
    L = np.zeros_like(A, dtype=float)

    for i in range(n):
        diag_sum = 0.0
        for k in range(i):
            diag_sum += L[i, k] * L[i, k]

        diag_value = A[i, i] - diag_sum
        if diag_value < 0.0 and diag_value > -1e-12:
            diag_value = 0.0
        L[i, i] = np.sqrt(diag_value)

        for j in range(i + 1, n):
            if A[j, i] != 0.0:
                entry_sum = 0.0
                for k in range(i):
                    entry_sum += L[i, k] * L[j, k]

                L[j, i] = (A[j, i] - entry_sum) / L[i, i]

    return L

